// How far back to ask DataHub for. Metering data lands about a day
// late, so "today" is always empty and asking for it is not an error,
// it is just a wasted row. 30 days is one invoice period plus slack.
const DAYS = 30;

const pad = (n) => String(n).padStart(2, '0');
const iso = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

const now = new Date();
const to = new Date(now);
to.setDate(to.getDate() - 1);          // yesterday, inclusive
const from = new Date(to);
from.setDate(from.getDate() - DAYS);

return [{
  json: {
    date_from: iso(from),
    date_to: iso(to),
    // Day. Hour would be 30x the rows for a chart that shows days.
    // Swap to 'Hour' only when the page actually draws hours.
    aggregation: 'Day',
  },
}];

// The token call answers { result: '<jwt>' }. Everything after this
// uses that, NOT the refresh token: the refresh token is a year-long
// credential and must not travel on every request.
const token = $json.result;
if (!token) {
  throw new Error('Eloverblik gav intet data access token. Er refresh-token udloebet?');
}
const cfg = $('Config').first().json;
return [{ json: { token, ...cfg } }];

// { result: [ { meteringPointId, streetName, buildingNumber, postcode,
//               cityName, typeOfMP, ... } ] }
const rows = ($json.result || []);
if (!rows.length) {
  throw new Error('Ingen maalepunkter paa kontoen.');
}
const prev = $('Udpak token').first().json;
const cfg = $('Config').first().json;

// Back-reference the Code node, never the HTTP node it unpacked.
// 'Hent data access token' answers { result: '<jwt>' } and has no
// .token, so this was undefined and 'Hent forbrug' sent
// 'Bearer undefined' - a 401 three nodes after the real mistake.
if (!prev.token) {
  throw new Error('Intet data access token i kaeden. Peger denne node paa Udpak token?');
}

const meters = rows.map((r) => ({
  id: String(r.meteringPointId || ''),
  address: [r.streetName, r.buildingNumber, r.postcode, r.cityName]
    .filter(Boolean).join(' ').trim(),
  type: String(r.typeOfMP || ''),
}));

return [{
  json: {
    token: prev.token,
    ...cfg,
    meters,
    ids: meters.map((m) => m.id),
  },
}];

// Eloverblik answers in CIM / Ebix shape, which is deeply nested and
// uses strings for every number:
//
//   result[].MyEnergyData_MarketDocument.TimeSeries[]
//     .Period[] { timeInterval:{start,end},
//                 Point[]{ position, 'out_Quantity.quantity' } }
//
// That last key is FLAT. The dot is part of the key name, not a
// nesting, which is how Eloverblik serialises CIM to JSON.
//
// Flatten to one row per day. Consumption is stored as INTEGER
// thousandths of a kWh (kwh_x1000) - the no-floats rule in
// CLAUDE.md applies to meter readings for the same reason it applies
// to money, and Eloverblik reports three decimals so nothing is lost.

const toX1000 = (s) => {
  const n = parseFloat(String(s == null ? '0' : s).replace(',', '.'));
  return isNaN(n) ? 0 : Math.round(n * 1000);
};

// Eloverblik timestamps are UTC. A Danish day starts at 22:00Z in
// summer and 23:00Z in winter, so taking the UTC date labels every
// reading ONE DAY EARLY. Nothing on a bar chart would ever show that.
//
// And the offset cannot be added in milliseconds either: the last
// Sunday in October is 25 hours long, so a 30-day window that spans
// it would drift by an hour and eventually by a day.
//
// So: resolve the start to a Danish CALENDAR date, then add whole
// days to that date at UTC noon, which no DST shift can move across
// a midnight.
const DK = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Copenhagen',
  year: 'numeric', month: '2-digit', day: '2-digit',
});
const pad = (n) => String(n).padStart(2, '0');
const dayOf = (isoStr, offsetDays) => {
  const base = DK.format(new Date(isoStr));            // YYYY-MM-DD, Danish
  const [y, m, d] = base.split('-').map(Number);
  const noon = new Date(Date.UTC(y, m - 1, d, 12, 0, 0));
  noon.setUTCDate(noon.getUTCDate() + offsetDays);
  return `${noon.getUTCFullYear()}-${pad(noon.getUTCMonth() + 1)}-${pad(noon.getUTCDate())}`;
};

const prev = $('Udpak maalepunkter').first().json;
const byDay = new Map();

// Reading p.out_Quantity.quantity returns undefined, because there is
// no out_Quantity object - the key is the whole string
// 'out_Quantity.quantity'. The old nested read fell through to '0' and
// published thirty days of 0,000 kWh with nothing raising an error.
// Both shapes are accepted here so a future flattening change cannot
// break it the other way.
const quantityOf = (p) => {
  if (p['out_Quantity.quantity'] != null) { return p['out_Quantity.quantity']; }
  if (p.out_Quantity && p.out_Quantity.quantity != null) { return p.out_Quantity.quantity; }
  return null;
};

let seen = 0;
let missing = 0;
let firstPoint = null;

for (const item of $input.all()) {
  const results = (item.json && item.json.result) || [];
  for (const r of results) {
    const doc = r.MyEnergyData_MarketDocument || {};
    for (const ts of (doc.TimeSeries || [])) {
      for (const per of (ts.Period || [])) {
        const start = (per.timeInterval || {}).start;
        if (!start) { continue; }
        for (const p of (per.Point || [])) {
          // position is 1-based within the period
          const pos = parseInt(p.position, 10);
          if (isNaN(pos)) { continue; }
          const day = dayOf(start, pos - 1);
          const raw = quantityOf(p);
          seen += 1;
          if (firstPoint === null) { firstPoint = p; }
          if (raw == null) { missing += 1; }
          byDay.set(day, (byDay.get(day) || 0) + toX1000(raw));
        }
      }
    }
  }
}

// One missing reading is ordinary. EVERY reading missing means the
// response shape has moved, and posting a flat zero line to Jytte
// would read as a month without electricity. Fail the node instead,
// and name the keys that were actually there.
if (seen > 0 && missing === seen) {
  throw new Error('Ingen maalinger kunne laeses ud af '
    + seen + ' punkter. Point-noeglerne er: '
    + Object.keys(firstPoint || {}).join(', '));
}

const days = [...byDay.entries()]
  .sort((a, b) => (a[0] < b[0] ? -1 : 1))
  .map(([date, x1000]) => ({
    date,
    kwh_x1000: x1000,
    kwh: (x1000 / 1000).toFixed(3).replace('.', ','),
  }));

// Bar heights, so the page does no arithmetic. Guard the all-zero
// case: dividing by a zero max would make every bar NaN%.
const top = days.reduce((m, d) => Math.max(m, d.kwh_x1000), 0) || 1;
for (const d of days) {
  d.bar = Math.max(2, Math.round((100 * d.kwh_x1000) / top));
}

const total = days.reduce((s, d) => s + d.kwh_x1000, 0);

return [{
  json: {
    ready: days.length > 0,
    reason: days.length ? '' : 'Eloverblik svarede, men uden maalinger i perioden.',
    source: 'eloverblik',
    meters: prev.meters || [],
    days,
    total_kwh: (total / 1000).toFixed(1).replace('.', ','),
    total_kwh_x1000: total,
    period: { from: prev.date_from, to: prev.date_to },
    // Declared so /poc/systems can judge this widget instead of
    // printing "kadence ukendt". Daily, with a generous staleness
    // window because DataHub itself is a day behind.
    expected_minutes: 1440,
    stale_after_minutes: 2880,
    fetched_at: new Date().toISOString(),
  },
}];
